<style>
.sales-status{display:inline-flex;border:1px solid #a7e0c3;background:#ecfdf5;color:#047857;border-radius:20px;padding:4px 10px;font-size:10px;font-weight:600}.sales-status-pending{background:#f4f6f5;border-color:#dde6e1;color:#52635b}.sales-status-alert{background:#fff8eb;border-color:#f5d18a;color:#9a5700}.sales-customer{font-size:10px;font-weight:400;color:#7b8982;margin-top:4px}
.sales-filters{margin:0 0 16px;color:#52635b;font-size:12px}.sales-filter-toolbar{display:flex;align-items:end;gap:12px}.sales-search-label{flex:1;max-width:440px}.sales-filters label{display:block;font-size:12px;font-weight:500;margin-bottom:6px}.sales-filters input:not([type=radio]):not([type=hidden]),.sales-filters select{width:100%;min-width:0;border:1px solid #dde6e1;border-radius:10px;background:white;padding:9px 11px;color:#34483f;font:inherit;margin:5px 0 9px}.sales-filters input:focus,.sales-filters select:focus{outline:2px solid #1f6f5b;outline-offset:1px}.sales-filters button{border:1px solid #dde6e1;border-radius:10px;background:#173f35;color:white;padding:10px 16px;font-size:12px;font-weight:600;cursor:pointer}.sales-filters button:focus-visible,.sales-filters a:focus-visible,.sales-filter-chips a:focus-visible{outline:2px solid #1f6f5b;outline-offset:3px}.sales-filter-toolbar>button{margin-bottom:15px}.sales-filter-badge{margin-left:5px;border-radius:12px;background:white;color:#173f35;padding:1px 6px}.sales-filter-panel{border:1px solid #dde6e1;border-radius:16px;background:white;margin-top:12px;box-shadow:0 5px 20px #173f3508}.sales-filter-panel[hidden],.sales-filter-backdrop[hidden],#salesCustomDates[hidden],#salesProductResults[hidden]{display:none}.sales-filter-panel header{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid #edf1ef}.sales-filter-panel h3{font-size:14px;font-weight:600;color:#24312c}.sales-filter-panel header button{background:white;color:#52635b;padding:6px 10px}.sales-filter-content{padding:18px}.sales-filter-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.sales-filters fieldset{border:0;padding:0;margin:0 0 16px;min-width:0}.sales-filters legend{font-size:11px;font-weight:600;color:#7b8982;margin-bottom:9px}.sales-filters .sales-radio{display:flex;align-items:center;gap:8px;margin-bottom:10px;font-weight:400;color:#34483f}.sales-radio input{appearance:auto;accent-color:#111;width:16px;height:16px;margin:0;flex-shrink:0}.sales-filter-hint{color:#7b8982;font-size:11px;line-height:1.5;margin:7px 0}.sales-product-picker{border-top:1px solid #edf1ef;padding-top:14px;max-width:500px}.sales-product-picker button{background:white;color:#52635b;padding:6px 10px}.sales-product-picker ul{max-height:180px;overflow:auto;border:1px solid #dde6e1;border-radius:10px;list-style:none;padding:5px}.sales-product-picker li button{width:100%;text-align:left;border:0}.sales-product-picker li button:hover{background:#eef5f1}.sales-filter-panel footer{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid #edf1ef;padding:14px 18px;background:white;border-radius:0 0 16px 16px}.sales-filter-panel footer a{color:#52635b;font-weight:600}.sales-filter-chips{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 16px}.sales-filter-chips:empty{margin:0}.sales-filter-chips a{display:inline-flex;gap:8px;align-items:center;border:1px solid #dde6e1;border-radius:20px;background:white;padding:5px 10px;font-size:11px;color:#34483f}.sales-filter-chips .sales-clear-all{border:0;background:transparent;color:#1f6f5b}.sales-filter-errors{background:#fff5f5;border:1px solid #f5bcbc;border-radius:10px;padding:12px;color:#b42318;margin:10px 0}.sales-filter-errors ul{list-style:disc;padding-left:18px}.sales-pagination{padding:16px}.sales-filter-backdrop{display:none}
@media(max-width:640px){.sales-filter-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.sales-filter-panel{position:fixed;inset:6vh 0 0;margin:0;z-index:1001;border-radius:18px 18px 0 0;display:flex;flex-direction:column;box-shadow:0 -10px 40px #173f3533}.sales-filter-panel header,.sales-filter-panel footer{flex-shrink:0}.sales-filter-content{overflow:auto;overscroll-behavior:contain;flex:1;min-height:0}.sales-filter-panel footer{padding-bottom:max(16px,env(safe-area-inset-bottom));border-radius:0}.sales-filter-backdrop{display:block;position:fixed;inset:0;background:#0006;z-index:1000}.sales-filter-toolbar{gap:8px}.sales-filter-toolbar>button{padding:10px}.sales-product-picker{max-width:none}}
@media(max-width:380px){.sales-filter-grid{grid-template-columns:1fr}}
</style>
